function migrateNames(value){if(typeof value==='string')return value.replaceAll('颜清佩','严钦佩').replace(/^若清$/,'李若清').replaceAll('蒋明婷','蒋云亭').replaceAll('严钦佩','严钦佩').replace(/\bOO\b/g,'欧欧');if(Array.isArray(value))return value.map(migrateNames);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k==='颜清佩'?'严钦佩':k==='若清'?'李若清':k,migrateNames(v)]));return value}db=migrateNames(db);function migrateProjects(v){if(Array.isArray(v))return v.map(migrateProjects);if(v&&typeof v==='object'){for(const k of Object.keys(v)){if(k==='project'&&v[k]==='reading')v[k]='culture';else v[k]=migrateProjects(v[k])}}return v}db=migrateProjects(db);db.tasks.forEach(t=>{if(t.project==='q3'&&(t.routineLabel||t.phaseLabel))t.project='research'});if(!names.includes(db.user))db.user='David';save();

