const LocalRepository={async listTasks(){return db.tasks},async saveTask(t){const i=db.tasks.findIndex(x=>x.id===t.id);i<0?db.tasks.push(t):db.tasks[i]=t;save();return t},async recordUpdate(u){db.updates.push(u);save();return u},async getSession(){return{mode:'demo',displayName:db.user,authenticated:false}}};
class HTTPRepository{constructor(base=window.WORKBENCH_API_BASE){this.base=base}async call(path,method='GET',body){const r=await fetch(this.base+path,{method,credentials:'include',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('服务请求失败：'+r.status);return r.json()}listTasks(){return this.call('/tasks')}saveTask(t){return this.call('/tasks/'+t.id,'PUT',t)}recordUpdate(u){return this.call('/updates','POST',u)}getSession(){return this.call('/auth/session')}generateReport(body){return this.call('/reports/generate','POST',body)}presignUpload(body){return this.call('/files/presign','POST',body)}}
