function tag(s,c=''){return`<span class="tag ${c}">${esc(s)}</span>`}function progress(ts){return ts.length?Math.round(ts.filter(t=>t.status==='已完成').length/ts.length*100):0}function nav(p){page=p;filter='全部';render()}function modal(html){document.getElementById('modal').innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true"><div class="between"><h2>${html.title}</h2><button aria-label="关闭" onclick="closeModal()">✕</button></div>${html.body}</section></div>`}function closeModal(){document.getElementById('modal').innerHTML=''}
function render(){if(page!=='welcome'&&window.teamSession!==db.user)page='welcome';syncDuties();syncRules();if(page==='welcome'){renderWelcome();return}const pages=[['welcome','◇','团队首页'],['today','◫','我的今天'],['projects','▤','项目与成果'],['team','◉','团队总览'],['meeting','▦','规则设置'],['reports','▧','报告中心'],['settings','⚙','设置与接口']];document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand brandimage"><img src="./assets/logo.png" alt="致知资本 ZHI CAPITAL"></div><nav class="nav">${pages.map(([p,i,n])=>`<button class="${page===p?'active':''}" onclick="nav('${p}')"><span>${i}</span>${n}</button>`).join('')}</nav><div class="sidefoot"><span class="live"></span>工作有序，成果可见<br><br>团队工作台 · V1.0<br>投资研究 / 培训与文化</div></aside><main class="main"><header class="top"><div class="crumb">工作空间 &nbsp; / &nbsp; ${pages.find(x=>x[0]===page)[2]}</div><div class="topright">${tag('账号已验证 · 工作数据仅本机','blue')}<span class="note">${today()}</span><div><span class="avatar">${esc(db.user.slice(0,1))}</span><span>${esc(db.user)}</span><button class="note" style="margin-left:12px" onclick="logoutTeam()">退出</button></div></div></header><div class="content">${({today:viewToday,projects:viewProjects,team:viewTeam,meeting:viewRules,reports:viewReports,settings:viewSettings})[page]()}</div></main></div>`}
function heading(title,sub,action=''){return`<div class="titlebar"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function taskRow(t){return`<div class="task compacttask ${dutyOverdue(t)?'dutyred':''}"><button class="check ${t.status==='已完成'?'done':''}" aria-label="更新${esc(t.title)}" onclick="editTask('${t.id}')">${t.status==='已完成'?'✓':''}</button><button class="tasktitle" title="${esc(t.title)}" onclick="editTask('${t.id}')">${esc(t.title)}</button><span class="taskproject" title="${esc(pn(t.project))}">${esc(pn(t.project))}</span><span class="taskdue" title="截止日期">${esc(t.due)}</span><button class="taskstatus" onclick="editTask('${t.id}')">${tag(t.status,statusColor(t.status))}</button></div>`}

