function saveInsight(e){e.preventDefault();const content=String(new FormData(e.target).get('content')).trim();if(!content)return toast('请写下一项今日收获');db.insights??=[];const i=db.insights.findIndex(x=>x.owner===db.user&&x.date===today()),record={id:i>=0?db.insights[i].id:uid(),owner:db.user,date:today(),content,updated:new Date().toISOString()};if(i>=0)db.insights[i]=record;else db.insights.push(record);save();render();toast('今日收获已保存，将纳入对应日期的报告')}
function leaveForm(){const ls=(db.leaves||[]).filter(l=>l.owner===db.user);modal({title:'请假登记',body:`<p class="note">仅保存本机记录，尚未提交审批。</p><form onsubmit="saveLeave(event)"><div class="formrow"><div><label>开始日期</label><input type="date" name="start" value="${today()}" required></div><div><label>结束日期</label><input type="date" name="end" value="${today()}" required></div></div><label>类型</label><select name="type"><option>事假</option><option>年假</option><option>病假</option><option>其他</option></select><div class="actions"><button class="btn">保存登记</button></div></form><h3 style="margin-top:20px">我的登记记录</h3>${ls.map(l=>`<div class="notice between"><span>${l.start} — ${l.end} · ${esc(l.type)}</span><button class="note" onclick="removeLeave('${l.id}')">撤销</button></div>`).join('')||'<p class="note">暂无记录</p>'}`})}
function saveLeave(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.end<f.start)return toast('结束日期不能早于开始日期');db.leaves??=[];db.leaves.push({id:uid(),owner:db.user,...f});save();closeModal();render();toast('已保存本机登记，未提交审批')}
