function addOtherTask(e){e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title)return toast('请填写工作内容');const t=task(db.user,title,f.get('project'),'其他工作','未开始','');db.tasks.push(t);save();render();toast('已加入待办清单')}
function updateCommunity(value){db.communityChecks??={};const prior=db.communityChecks[today()];const existing=db.tasks.find(t=>t.owner==='杨瑞'&&t.communityDate===today());if(value==='chat'&&existing&&(existing.updated||existing.status!=='未开始')){toast('已有复盘进展，请先核对任务记录');render();return}db.communityChecks[today()]=value;if(value==='investment'||value==='substantive'){const title=value==='investment'?'君汇社群复盘：总结 David 今日投资发言':'君汇社群复盘：整理今日实质内容';if(existing){existing.title=title}else{const t=task('杨瑞',title,'culture','常规工作','未开始','整理核心观点、依据与后续问题，附原文或记录来源');t.communityDate=today();db.tasks.push(t)}}else if(existing){db.tasks=db.tasks.filter(t=>t.id!==existing.id)}save();render();toast(value==='chat'?'今日仅闲聊，已记录跳过':value?'复盘已加入待办清单':'已清除选择')}

function editTask(id){const t=db.tasks.find(x=>x.id===id)||{owner:db.user,title:'',project:'q3',type:'项目任务',status:'未开始',due:today(),next:'',result:'',link:''};modal({title:id?'任务详情与进展':'新建任务',body:`<form onsubmit="submitTask(event,'${id||''}')">${t.dutyInstructions?`<div class="notice"><strong>值班工作要求</strong><p style="white-space:pre-wrap">${esc(t.dutyInstructions)}</p></div>`:''}<label>任务名称</label><input name="title" required value="${esc(t.title)}"><div class="formrow"><div><label>负责人</label><select name="owner">${names.map(n=>`<option ${n===t.owner?'selected':''}>${n}</option>`).join('')}</select></div><div><label>所属项目</label><select name="project">${projects.map(p=>`<option value="${p.id}" ${p.id===t.project?'selected':''}>${p.name}</option>`).join('')}</select></div></div><div class="formrow"><div><label>任务类型</label><select name="type">${[...new Set(['周期任务','事件任务','项目任务','主动改进','常规工作',t.type])].map(x=>`<option ${x===t.type?'selected':''}>${x}</option>`).join('')}</select></div><div><label>截止日期</label><input type="date" name="due" required value="${esc(t.due)}"></div></div><label>当前状态</label><select name="status">${['未开始','进行中','待协作','待复核','已完成'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select><label>关键进展 / 成果（完成任务时必填）</label><textarea name="result" placeholder="例如：完成 8 家公司初筛，发现 2 项待核实问题">${esc(t.result)}</textarea><label>下一步 / 需要的帮助</label><input name="next" value="${esc(t.next)}"><label>成果链接（可选）</label><input name="link" type="url" placeholder="https://…" value="${esc(t.link)}"><p class="note">文件上传接口已预留，当前请粘贴已有文件链接。</p><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">取消</button><button class="btn">保存进展</button></div></form>`})}
async function submitTask(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.status==='已完成'&&!f.result.trim())return toast('请补充完成成果，让报告有据可查');const t={...f,id:id||uid(),updated:new Date().toISOString()};const old=db.tasks.find(x=>x.id===id);if(old)Object.assign(t,{routineDate:old.routineDate,routineLabel:old.routineLabel,communityDate:old.communityDate,phaseWeek:old.phaseWeek,phaseLabel:old.phaseLabel,dutyKey:old.dutyKey,dutyKind:old.dutyKind,dutyInstructions:old.dutyInstructions,assignmentKey:old.assignmentKey,meetingSource:old.meetingSource,meetingWeek:old.meetingWeek,ruleId:old.ruleId,ruleKey:old.ruleKey});await repo.saveTask(t);await repo.recordUpdate({id:uid(),taskId:t.id,owner:t.owner,date:today(),status:t.status,result:t.result,next:t.next,title:t.title,link:t.link});closeModal();render();toast('任务与工作记录已保存')}
function dailyUpdate(){const ts=db.tasks.filter(t=>t.owner===db.user);if(!ts.length)return editTask();modal({title:'更新今天工作',body:`<p class="sub">选择有进展的任务，补充一句关键变化。未选择的任务保持原状。</p><form onsubmit="submitDaily(event)">${ts.map(t=>`<div class="notice"><label style="margin:0;font-size:13px;color:var(--navy)"><input type="checkbox" name="pick" value="${t.id}"> ${esc(t.title)}</label><div class="formrow"><select name="status_${t.id}" aria-label="任务状态">${['未开始','进行中','待协作','待复核','已完成'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><input name="result_${t.id}" aria-label="关键进展" placeholder="本次关键进展 / 成果"></div><input style="margin-top:8px" name="next_${t.id}" aria-label="下一步" placeholder="下一步 / 需要谁帮助（可选）"></div>`).join('')}<div class="actions"><button class="btn secondary" type="button" onclick="closeModal()">取消</button><button class="btn">保存并生成今日汇总</button></div></form>`})}
async function submitDaily(e){e.preventDefault();const f=new FormData(e.target),ids=f.getAll('pick');if(!ids.length)return toast('请先选择今天有进展的任务');for(const id of ids){if(!String(f.get('result_'+id)).trim())return toast('请为选中的任务补充一句关键进展')}for(const id of ids){const t=db.tasks.find(t=>t.id===id);t.status=f.get('status_'+id);t.result=f.get('result_'+id).trim();t.next=f.get('next_'+id).trim()||t.next;t.updated=new Date().toISOString();await repo.saveTask(t);await repo.recordUpdate({id:uid(),taskId:id,title:t.title,date:today(),owner:t.owner,status:t.status,result:t.result,next:t.next,link:t.link})}closeModal();generate('日报',db.user,today(),today());page='reports';render();toast('今日进展已保存，汇总已生成')}
function viewProjects(){return heading('项目与成果','从阶段推进到最终交付，每一项成果都有出处。',`<button class="btn" onclick="editTask()">＋ 新建任务</button>`)+`<div class="grid2">${projects.map(p=>{const ts=db.tasks.filter(t=>t.project===p.id);return`<section class="panel"><div class="between">${tag(p.category,p.category==='投资与分析'?'blue':'purple')}<span class="note">${p.date}</span></div><h2 style="margin-top:17px">${p.name}</h2><p class="sub">${p.desc}</p><div class="progress" style="margin-top:25px"><i style="width:${progress(ts)}%"></i></div><div class="between note"><span>负责人：${p.owner}</span><span>${progress(ts)}% · 任务完成比例</span></div><div class="notice"><strong>交付物</strong><p>${p.deliver}</p></div><div class="between" style="margin-top:20px"><span class="note">${ts.length} 项任务 · ${ts.filter(t=>t.result).length} 项有成果记录</span><button class="btn secondary small" onclick="projectDetail('${p.id}')">查看项目 →</button></div></section>`}).join('')}</div>`}
function projectDetail(id){const p=projects.find(p=>p.id===id),ts=db.tasks.filter(t=>t.project===id);modal({title:p.name,body:`<p class="sub">${p.desc}</p>${id==='q3'?'<div class="notice"><strong>行业初筛 → 市场筛选 → 重点研究 → 复核发布</strong><p>筛选分类：重点研究 / 持续观察 / 异常待核实 / 暂无明显信号。关键数据与判断保留来源。</p></div>':''}${ts.map(t=>`<div class="notice"><div class="between"><strong>${esc(t.owner)} · ${esc(t.title)}</strong>${tag(t.status,statusColor(t.status))}</div><p>成果：${esc(t.result||'尚未提交')}</p><p>下一步：${esc(t.next)}</p>${safeLink(t.link)}<button class="note" onclick="editTask('${t.id}')">更新任务 →</button></div>`).join('')}`})}
function safeLink(s){try{const u=new URL(s);if(!['https:','http:'].includes(u.protocol))return'';return`<p><a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">打开成果链接 ↗</a></p>`}catch{return''}}
function viewTeam(){return heading('团队总览','先看需要协调的问题，再看项目与个人成果。',`<button class="btn" onclick="reportForm('团队')">生成团队报告</button>`)+`<div class="banner" style="margin-bottom:22px">演示视图可切换所有成员；正式接入后由后台按账号、公司和角色校验权限。第六位研究员及职责待补充。</div><section class="panel"><h2>需要协调</h2>${db.tasks.filter(t=>t.status==='待协作'||(t.due<today()&&t.status!=='已完成')).map(taskRow).join('')||'<div class="empty">目前没有已记录的阻塞或逾期事项。</div>'}</section><section class="panel"><div class="panelhead"><h2>全员工作情况</h2>${tag('依据已提交记录')}</div><div class="tablewrap"><table><thead><tr><th>成员 / 职责</th><th>当前重点</th><th>任务完成</th><th>今日更新</th><th>协作</th><th></th></tr></thead><tbody>${names.filter(n=>n!=='David').map(n=>{const ts=db.tasks.filter(t=>t.owner===n),up=db.updates.filter(u=>u.owner===n&&u.date===today());return`<tr><td><strong>${n}</strong><div class="sub">${roles[names.indexOf(n)]}</div></td><td>${esc(ts.find(t=>t.status!=='已完成')?.title||'暂无待办')}</td><td>${ts.filter(t=>t.status==='已完成').length} / ${ts.length}</td><td>${tag(up.length?'已更新':'未更新',up.length?'green':'')}</td><td>${ts.filter(t=>t.status==='待协作').length}</td><td><button class="note" onclick="startDay('${n}')">查看 →</button></td></tr>`}).join('')}</tbody></table></div></section>`}
function viewMeeting(){return heading('例会与分享','周五收集主题，周一对齐行动。',`<button class="btn" onclick="shareForm()">＋ 申报核心分享</button>`)+`${weeklyPanel()}<div class="columns"><div><section class="panel"><div class="panelhead"><h2>核心分享预告</h2>${tag('待确认议程','blue')}</div>${db.shares.length?db.shares.map(s=>`<div class="notice"><div class="between"><h3>${esc(s.subject)}</h3>${tag(s.owner)}</div><p>分享日期：${esc(s.date)} · ${esc(s.minutes)} 分钟</p><p>核心观点：${esc(s.point)}</p><p>待讨论：${esc(s.question)}</p>${safeLink(s.link)}</div>`).join(''):'<div class="empty">还没有分享申报。<br>周五填写标的、核心观点和待讨论问题。</div>'}</section><section class="panel"><div class="panelhead"><h2>会议结论与后续行动</h2><button class="btn secondary small" onclick="meetingAction()">＋ 记录行动</button></div>${db.minutes.map(m=>`<div class="notice"><strong>${esc(m.conclusion)}</strong><p>${esc(m.owner)} · 截止 ${esc(m.due)} · 已关联任务</p></div>`).join('')||'<div class="empty">把会议结论落实为有负责人和截止日期的任务。</div>'}</section></div><aside><section class="panel"><h2>周一例会议程</h2><div class="timeline"><div><strong>01 · 上周工作回顾</strong><p>成果、未完成事项与原因。</p></div><div><strong>02 · 本周工作计划</strong><p>本周目标、交付物与协作需求。</p></div><div><strong>03 · 核心标的分享</strong><p>研究判断、证据、风险与待验证问题。</p></div><div><strong>04 · 确认后续行动</strong><p>明确负责人和截止时间。</p></div></div><button class="btn secondary" onclick="meetingPreview()">生成会前预告</button></section><div class="banner">周五提醒与周一自动汇总：定时任务接口待接入，当前支持手动生成。</div></aside></div>`}
function shareForm(){modal({title:'申报核心分享',body:`<form onsubmit="submitShare(event)"><label>标的 / 分享主题</label><input name="subject" required><div class="formrow"><div><label>分享人</label><select name="owner">${names.map(n=>`<option ${db.user===n?'selected':''}>${n}</option>`).join('')}</select></div><div><label>分享日期</label><input type="date" name="date" value="${today()}" required></div></div><label>一句话核心观点</label><textarea name="point" required></textarea><label>希望讨论的问题</label><input name="question" required><label>预计时长（分钟）</label><input name="minutes" type="number" min="1" max="180" value="15" required><label>材料链接（可选）</label><input name="link" type="url"><div class="actions"><button class="btn">保存申报</button></div></form>`})}
function submitShare(e){e.preventDefault();db.shares.push({id:uid(),...Object.fromEntries(new FormData(e.target))});save();closeModal();render();toast('分享已加入预告')}
function meetingAction(){modal({title:'记录会议结论并创建任务',body:`<form onsubmit="submitAction(event)"><label>会议结论 / 后续行动</label><textarea name="conclusion" required></textarea><label>负责人</label><select name="owner">${names.map(n=>`<option>${n}</option>`).join('')}</select><label>所属项目</label><select name="project">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select><label>截止日期</label><input name="due" type="date" required value="${today()}"><div class="actions"><button class="btn">确认并创建任务</button></div></form>`})}
function submitAction(e){e.preventDefault();const m={id:uid(),...Object.fromEntries(new FormData(e.target))};const t=task(m.owner,m.conclusion,m.project,'事件任务','未开始','落实会议结论',m.due);m.taskId=t.id;db.minutes.push(m);db.tasks.push(t);save();closeModal();render();toast('会议行动已进入负责人任务列表')}
function meetingPreview(){const s=db.shares.filter(s=>s.date>=today()).sort((a,b)=>a.date.localeCompare(b.date));modal({title:'会前预告 · 规则汇总',body:`<div class="report">${esc('核心分享预告\n\n'+(s.map(s=>`${s.date}｜${s.owner}｜${s.subject}（${s.minutes} 分钟）\n观点：${s.point}\n讨论：${s.question}`).join('\n\n')||'尚未申报下次分享。')+'\n\n待协调事项\n'+(db.tasks.filter(t=>t.status==='待协作').map(t=>`${t.owner}：${t.title}；${t.next}`).join('\n')||'暂无已记录的待协调事项。'))}</div>`})}
function generate(type,owner,start,end){const us=db.updates.filter(u=>(owner==='团队'||u.owner===owner)&&u.date>=start&&u.date<=end);const latest=new Map();us.forEach(u=>latest.set(u.taskId,u));const records=[...latest.values()];const tasks=db.tasks.filter(t=>owner==='团队'||t.owner===owner);const text=`${owner} · ${type}\n${start} 至 ${end}\n\n一、关键进展与成果\n${records.map(u=>`• ${u.owner}｜${u.title}［${u.status}］\n  ${u.result||'未填写成果'}\n  下一步：${u.next||'未填写'}`).join('\n')||'本期尚无已提交的工作更新，不能据此判断未开展工作。'}\n\n二、需要协作\n${records.filter(u=>u.status==='待协作').map(u=>`• ${u.owner}：${u.title}；${u.next}`).join('\n')||'本期记录中暂无待协作事项。'}\n\n三、当前后续计划（生成时快照）\n${tasks.filter(t=>t.status!=='已完成').map(t=>`• ${t.owner}｜${t.title}｜${t.due}｜${t.next}`).join('\n')||'暂无待推进任务。'}\n\n记录依据：${us.length} 次更新，涉及 ${records.length} 项任务。同一任务按本期最新更新汇总。\n生成方式：本机规则汇总；AI 尚未接入。`;
const insights=(db.insights||[]).filter(i=>(owner==='团队'||i.owner===owner)&&i.date>=start&&i.date<=end);const insightText=insights.length?'\n\n四、今日收获 / 重点分享\n'+insights.map(i=>i.date+'｜'+i.owner+'：'+i.content).join('\n'):'';const r={id:uid(),type,owner,start,end,created:new Date().toISOString(),text:text+insightText,insights:insights.map(i=>({...i})),sources:records.map(u=>({...u}))};db.reports.unshift(r);selectedReport=r.id;save();return r}
function viewReports(){const r=db.reports.find(r=>r.id===selectedReport)||db.reports[0];return heading('报告中心','一次更新，持续沉淀。每条进展都能回到原始记录。',`<button class="btn" onclick="reportForm()">＋ 生成报告</button>`)+`<div class="banner" style="margin-bottom:22px">当前为规则汇总，非真实 AI。日报、周报可立即试用；月报、季度报、年报提供按周期汇总，目标评估将在后台接入后完善。</div><div class="columns" style="grid-template-columns:280px minmax(0,1fr)"><section class="panel reportlist"><h2 style="margin-bottom:15px">报告记录</h2>${db.reports.map(x=>`<button onclick="selectedReport='${x.id}';render()" style="background:${x.id===r?.id?'#f0f4ff':'transparent'}"><strong>${esc(x.owner)} · ${x.type}</strong><div class="note">${x.start} — ${x.end}</div></button>`).join('')||'<div class="empty">暂无报告</div>'}</section><section class="panel">${r?`<div class="panelhead"><h2>${esc(r.owner)} · ${r.type}</h2><button class="btn secondary small" onclick="exportReport('${r.id}')">导出 Markdown ↓</button></div><p class="note">生成时间：${new Date(r.created).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})} · 历史快照</p><div class="report">${esc(r.text)}</div><h3 style="margin-top:22px">来源记录</h3>${r.sources.map(u=>`<div class="notice"><button class="tasktitle" onclick="editTask('${u.taskId}')">${esc(u.owner)} · ${esc(u.title)} ↗</button><p>${u.date} · ${esc(u.result||'未填写成果')}</p>${safeLink(u.link)}</div>`).join('')||'<p class="note">本期无更新来源。</p>'}`:'<div class="empty">更新今天工作后，生成第一份报告。<br><button class="btn" style="margin-top:20px" onclick="reportForm()">生成报告</button></div>'}</section></div>`}
function reportForm(owner=db.user){modal({title:'生成工作报告',body:`<form onsubmit="submitReport(event)"><div class="formrow"><div><label>报告范围</label><select name="owner">${['团队',...names].map(n=>`<option ${n===owner?'selected':''}>${n}</option>`).join('')}</select></div><div><label>报告周期</label><select name="type" onchange="setRange(this.form)">${['日报','周报','月报','季度报','年报'].map(n=>`<option>${n}</option>`).join('')}</select></div></div><div class="formrow"><div><label>开始日期</label><input type="date" name="start" value="${today()}" required></div><div><label>结束日期</label><input type="date" name="end" value="${today()}" required></div></div><p class="note">按实际更新日期筛选，保留来源与生成时的计划快照。</p><div class="actions"><button class="btn">生成汇总</button></div></form>`})}
function setRange(form){const end=today(),d=new Date(end+'T00:00:00Z'),type=form.elements.type.value;if(type==='周报')d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));if(type==='月报')d.setUTCDate(1);if(type==='季度报'){d.setUTCDate(1);d.setUTCMonth(Math.floor(d.getUTCMonth()/3)*3)}if(type==='年报'){d.setUTCDate(1);d.setUTCMonth(0)}form.elements.start.value=d.toISOString().slice(0,10);form.elements.end.value=end}
function submitReport(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.start>f.end)return toast('开始日期不能晚于结束日期');generate(f.type,f.owner,f.start,f.end);closeModal();nav('reports');toast('报告已生成，原始记录可追溯')}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function exportReport(id){const r=db.reports.find(x=>x.id===id);download(`${r.owner}_${r.type}_${r.end}.md`,r.text,'text/markdown')}
function rosterEdit(){modal({title:'两条狗 · 每周值班安排',body:`<form onsubmit="submitRoster(event)"><p class="sub">同一班次负责两条狗；换班请更新人员。周一大扫除由全员参与。</p>${db.roster.map((r,i)=>`<label>${r.day}</label><select name="day${i}">${['待分配',...names].map(n=>`<option ${n===r.person?'selected':''}>${n}</option>`).join('')}</select>`).join('')}<div class="actions"><button class="btn">保存值班表</button></div></form>`})}function submitRoster(e){e.preventDefault();const f=new FormData(e.target);db.roster.forEach((r,i)=>r.person=f.get('day'+i));save();closeModal();render();toast('值班安排已保存')}
function viewSettings(){return heading('设置与接口','先跑通工作流程，再连接组织的真实数据与服务。')+`<div class="grid2"><section class="panel"><div class="panelhead"><h2>服务连接</h2>${tag('尚未配置','orange')}</div>${[['账号与权限','/api/v1/auth/session','姓名密码验证已接入；组织权限与共享数据待接入'],['共享数据库','/api/v1/tasks · /updates','任务、进展与项目数据统一保存'],['文件存储','/api/v1/files/presign','申请上传地址，记录文件归属与访问权限'],['AI 报告','/api/v1/reports/generate','读取授权范围的更新记录，生成带来源的报告'],['后台定时任务','/api/v1/jobs','每日汇总、周五分享提醒、周一会前预告']].map(([n,u,d])=>`<div class="projectmini"><h3>${n}</h3><p class="note">${d}</p><code class="note">${u}</code></div>`).join('')}<p class="note">接口契约已放入项目源代码 API-CONTRACT.md。当前仅登录验证调用后台，其他业务接口尚未接入。</p></section><div><section class="panel"><h2>演示数据管理</h2><p class="sub">数据保存在当前浏览器，不会同步到其他设备。姓名密码已由服务端验证，业务数据尚未接入共享数据库。</p><button class="btn secondary" style="margin-top:20px" onclick="download('工作台数据备份.json',JSON.stringify(db,null,2),'application/json')">导出本机数据</button></section><section class="panel"><h2>待补充的组织信息</h2><div class="notice"><p>第六位研究员姓名与负责行业</p><p>公司名单、人员归属与权限</p><p>蒋云亭的研究范围及操作流程</p><p>值班表、固定活动时间与通知方式</p></div></section><section class="panel"><h2>插图与视觉</h2><p class="sub">深海军蓝 / 亮蓝 / 浅蓝与淡紫。个人首页预留品牌插图位，可替换为团队或品牌视觉。</p></section></div></div>`}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});bootTeam();

